-- Provisión de intereses (1.4.99.05 / B17 149905) contra intereses por cobrar (1.4.02 / B17 1402) al 30-sep-2025.
-- Pregunta de ASOPREP del 24-nov-2026 sobre el B17 de septiembre. Solo SELECT. Para otro mes, cambiar las fechas.
-- Mora contabilizada pendiente en 1.4.02 al 30-sep-2025 (misma regla de la conciliacion C27b) y provision de mora del libro
WITH x AS (
   SELECT m.PRSTCDGO, CASE m.MVICTPMV WHEN 5 THEN m.MVICVLOR ELSE -m.MVICVLOR END v FROM CRD.MVIC m
    WHERE m.MVICCMPN = 2 AND m.MVICTPMV IN (5, 6, 9) AND NVL(m.MVICANUL,0) = 0 AND TRUNC(m.MVICFCCT) <= DATE '2025-09-30'
   UNION ALL
   SELECT g.PRSTCDGO, -NVL(g.PGPRMRPG,0) FROM CRD.PGPR g WHERE NVL(g.PGPRANUL,0) = 0 AND g.PGPRFCHA >= DATE '2025-06-01' AND g.PGPRFCHA < DATE '2025-10-01')
SELECT ROUND(SUM(v),2) MORA_PEND_1402 FROM x;
SELECT MVICCMPN, ROUND(SUM(CASE WHEN MVICTPMV IN (1,4) THEN MVICVLOR WHEN MVICTPMV IN (2,3,9) THEN -MVICVLOR ELSE 0 END),2) PROV
FROM CRD.MVIC WHERE NVL(MVICANUL,0)=0 AND MVICFCCT <= DATE '2025-09-30' GROUP BY MVICCMPN ORDER BY 1;
-- Provision por antiguedad de la cuota (anos desde el vencimiento) al 30-sep
SELECT CASE WHEN d.DTPRFCVN < DATE '2020-01-01' THEN 'antes 2020' WHEN d.DTPRFCVN < DATE '2024-01-01' THEN '2020-2023' WHEN d.DTPRFCVN < DATE '2025-06-01' THEN '2024-may25' ELSE 'jun25-sep25' END RANGO,
 m.MVICCMPN, ROUND(SUM(CASE WHEN MVICTPMV IN (1,4) THEN MVICVLOR WHEN MVICTPMV IN (2,3,9) THEN -MVICVLOR ELSE 0 END),2) PROV
FROM CRD.MVIC m JOIN CRD.DTPR d ON d.DTPRCDGO=m.DTPRCDGO WHERE NVL(m.MVICANUL,0)=0 AND m.MVICFCCT <= DATE '2025-09-30' AND m.MVICCMPN IN (1,2)
GROUP BY CASE WHEN d.DTPRFCVN < DATE '2020-01-01' THEN 'antes 2020' WHEN d.DTPRFCVN < DATE '2024-01-01' THEN '2020-2023' WHEN d.DTPRFCVN < DATE '2025-06-01' THEN '2024-may25' ELSE 'jun25-sep25' END, m.MVICCMPN ORDER BY 1,2;
